class Solution:
    def numberOfZigzagArrays(self, n: int, m: int) -> int:
        MOD = 1_000_000_007
        if n == 1:
            return m % MOD
        dp_up = [0] * (m + 1)
        dp_down = [0] * (m + 1)
        for v in range(1, m + 1):
            dp_up[v] = v - 1
            dp_down[v] = m - v

        for _ in range(3, n + 1):
            next_up = [0] * (m + 1)
            next_down = [0] * (m + 1)
            pref = 0
            for v in range(1, m + 1):
                next_up[v] = pref
                pref = (pref + dp_down[v]) % MOD
            suff = 0
            for v in range(m, 0, -1):
                next_down[v] = suff
                suff = (suff + dp_up[v]) % MOD
            dp_up, dp_down = next_up, next_down

        return (sum(dp_up) + sum(dp_down)) % MOD

#include <vector>
#include <numeric>
using namespace std;

class Solution {
public:
    int numberOfZigzagArrays(int n, int m) {
        long long MOD = 1000000007;
        if (n == 1) return m % MOD;
        vector<long long> dp_up(m + 1, 0), dp_down(m + 1, 0);
        for (int v = 1; v <= m; ++v) {
            dp_up[v] = v - 1;
            dp_down[v] = m - v;
        }
        for (int step = 3; step <= n; ++step) {
            vector<long long> next_up(m + 1, 0), next_down(m + 1, 0);
            long long pref = 0;
            for (int v = 1; v <= m; ++v) {
                next_up[v] = pref;
                pref = (pref + dp_down[v]) % MOD;
            }
            long long suff = 0;
            for (int v = m; v >= 1; --v) {
                next_down[v] = suff;
                suff = (suff + dp_up[v]) % MOD;
            }
            dp_up = move(next_up);
            dp_down = move(next_down);
        }
        long long ans = 0;
        for (int v = 1; v <= m; ++v) {
            ans = (ans + dp_up[v] + dp_down[v]) % MOD;
        }
        return ans;
    }
};

